from pathlib import Path
import json,re

ROOT=Path('apps/painel-ldr/src')
cat=ROOT/'lib/professional-formations.catalog.ts'
s=cat.read_text()

new_slugs=[
 'jornalismo-digital','estetica-beleza','terapias-contemporaneas','copywriting-vendas','educacao-financeira','mediacao-conflitos'
]
# Extend the shared professional-formation catalog types without disturbing existing products.
m=re.search(r'export type PFSlug=([^;]+);',s)
if not m: raise SystemExit('PFSlug anchor not found')
current=m.group(1)
for slug in new_slugs:
    token=f'"{slug}"'
    if token not in current: current += f'|{token}'
s=s[:m.start()]+f'export type PFSlug={current};'+s[m.end():]

old='type T={name:string;short:string;description:string;project:string;modules:string[]};'
new='type T={name:string;short:string;description:string;project:string;modules:string[];category?:string;disclaimer?:string;portfolio?:string[]};'
if old in s: s=s.replace(old,new,1)
oldpf='export type PF={slug:PFSlug;productKey:string;publicPath:string;learnerPath:string;icon:string;theme:string;priceBrlCents:number;priceEurCents:number;hours:number;lessons:number;modulesCount:number;minimumDays:number;i18n:Record<PFLocale,T>};'
newpf='export type PF={slug:PFSlug;productKey:string;publicPath:string;learnerPath:string;icon:string;theme:string;priceBrlCents:number;priceEurCents:number;hours:number;lessons:number;modulesCount:number;minimumDays:number;includedInSubscription?:boolean;i18n:Record<PFLocale,T>};'
if oldpf in s: s=s.replace(oldpf,newpf,1)
if 'const advanced=' not in s:
    anchor='const common={priceBrlCents:29999,priceEurCents:4990,hours:600,lessons:150,modulesCount:10,minimumDays:75};'
    if anchor not in s: raise SystemExit('common anchor not found')
    s=s.replace(anchor,anchor+'\nconst advanced={priceBrlCents:29999,priceEurCents:4990,hours:600,lessons:150,modulesCount:15,minimumDays:75,includedInSubscription:false};',1)

