def ts(v):
    return json.dumps(v,ensure_ascii=False,separators=(',',':'))

def entry(f):
    loc=[]
    for code in ['pt','en','fr','es']:
        d=f[code].copy()
        loc.append(f'{code}:'+ts(d))
    return '{slug:'+ts(f['slug'])+',productKey:'+ts(f['productKey'])+',publicPath:'+ts(f['publicPath'])+',learnerPath:'+ts('/cliente/treinamentos/formacao-profissional/'+f['slug'])+',icon:'+ts(f['icon'])+',theme:'+ts(f['theme'])+',...advanced,i18n:{'+','.join(loc)+'}}'

if 'formacao_jornalismo_digital_comunicacao_comunidade' not in s:
    marker='\n];\nexport function getProfessionalFormation'
    if marker not in s: raise SystemExit('catalog end marker not found')
    block=',\n'+',\n'.join(entry(f) for f in formations)
    s=s.replace(marker,block+marker,1)

