new_builder=r'''export function buildLessons(f:PF,locale:PFLocale){
 const t=pfText(f,locale),perModule=Math.max(1,Math.floor(f.lessons/f.modulesCount));
 const L={
  pt:{lesson:"Aula",objective:"Objetivo de aprendizagem",question:"Pergunta central",concepts:"Conceitos fundamentais",context:"Contexto e desenvolvimento",caseLabel:"Estudo de caso",critical:"Análise crítica",practice:"Atividade prática",errors:"Erros e riscos",synthesis:"Síntese",refs:"Referências para aprofundamento"},
  en:{lesson:"Lesson",objective:"Learning objective",question:"Central question",concepts:"Core concepts",context:"Context and development",caseLabel:"Case study",critical:"Critical analysis",practice:"Practical activity",errors:"Errors and risks",synthesis:"Synthesis",refs:"Further reading"},
  fr:{lesson:"Leçon",objective:"Objectif d’apprentissage",question:"Question centrale",concepts:"Concepts fondamentaux",context:"Contexte et développement",caseLabel:"Étude de cas",critical:"Analyse critique",practice:"Activité pratique",errors:"Erreurs et risques",synthesis:"Synthèse",refs:"Pour approfondir"},
  es:{lesson:"Clase",objective:"Objetivo de aprendizaje",question:"Pregunta central",concepts:"Conceptos fundamentales",context:"Contexto y desarrollo",caseLabel:"Estudio de caso",critical:"Análisis crítico",practice:"Actividad práctica",errors:"Errores y riesgos",synthesis:"Síntesis",refs:"Referencias para profundizar"}
 }[locale];
 const angles={
  pt:["fundamentos e linguagem técnica","história, contexto e evolução","autores, modelos e conceitos centrais","diagnóstico do problema e critérios de análise","métodos, ferramentas e tomada de decisão","estudo de caso aplicado","laboratório e aplicação profissional","ética, limites, riscos e proteção de pessoas","avaliação de evidências, resultados e melhoria","integração ao projeto profissional"],
  en:["foundations and technical language","history, context and evolution","authors, models and central concepts","problem diagnosis and analysis criteria","methods, tools and decision-making","applied case study","lab and professional application","ethics, limits, risks and protection","evaluation of evidence, outcomes and improvement","integration into the professional project"],
  fr:["fondements et langage technique","histoire, contexte et évolution","auteurs, modèles et concepts centraux","diagnostic du problème et critères d’analyse","méthodes, outils et prise de décision","étude de cas appliquée","laboratoire et application professionnelle","éthique, limites, risques et protection","évaluation des preuves, résultats et amélioration","intégration au projet professionnel"],
  es:["fundamentos y lenguaje técnico","historia, contexto y evolución","autores, modelos y conceptos centrales","diagnóstico del problema y criterios de análisis","métodos, herramientas y toma de decisiones","caso aplicado","laboratorio y aplicación profesional","ética, límites, riesgos y protección","evaluación de evidencias, resultados y mejora","integración en el proyecto profesional"]
 }[locale];
 const safe=(x:string)=>x.toLowerCase();
 return t.modules.map((moduleTitle,mi)=>({id:mi+1,title:moduleTitle,lessons:Array.from({length:perModule},(_,li)=>{
  const n=mi*perModule+li+1,angle=angles[li%angles.length],subject=safe(moduleTitle);
  const title=`${L.lesson} ${n} · ${moduleTitle} — ${angle}`;
  const content=[
   `${L.objective}: dominar ${angle} no eixo ${subject}, relacionando teoria, contexto profissional e o projeto final “${t.project}”.`,
   `${L.question}: quais decisões, critérios e limites tornam ${subject} tecnicamente consistente, verificável e adequado ao contexto real de atuação?`,
   `${L.concepts}: identifique a terminologia própria de ${subject}, diferencie conceitos próximos e registre relações de causa, evidência, contexto e consequência. A leitura deve evitar simplificações e separar afirmações factuais, interpretações e hipóteses.`,
   `${L.context}: analise como ${subject} se desenvolve dentro de ${t.name}. Compare abordagens possíveis, observe mudanças históricas e tecnológicas quando pertinentes e conecte o conteúdo às demandas atuais do campo.`,
   `${L.caseLabel}: construa ou examine uma situação profissional plausível envolvendo ${subject}. Delimite o problema, os atores envolvidos, as informações disponíveis, o que ainda precisa ser verificado e duas alternativas de ação.`,
   `${L.critical}: compare as alternativas do caso, explicite vantagens, limites, riscos e possíveis efeitos não intencionais. Quando houver regra legal, clínica, financeira ou profissional, trate o conteúdo como educação e indique a necessidade de verificar fontes oficiais atuais.`,
   `${L.practice}: produza uma entrega específica sobre ${subject} — diagnóstico, roteiro, protocolo não invasivo, análise, texto, planilha, mapa de decisão, peça de comunicação ou plano — escolhendo o formato coerente com esta formação. Registre critérios usados e como o resultado será avaliado.`,
   `${L.errors}: evite copiar modelos sem adaptação, afirmar dados sem fonte, confundir opinião com evidência, prometer resultados e ultrapassar limites éticos ou profissionais. Revise a entrega considerando público, contexto, privacidade, segurança e clareza.`,
   `${L.synthesis}: resuma em cinco pontos o que muda na sua prática após estudar ${subject} e conecte essa síntese ao módulo anterior e ao próximo passo do projeto.`,
   `${L.refs}: priorize livros acadêmicos, artigos revisados por pares, documentos técnicos, normas e fontes oficiais pertinentes ao tema. Não use referências inventadas; registre autor, instituição, título e data quando consultar uma fonte.`
  ];
  return{id:`${f.slug}-m${mi+1}-l${li+1}`,title,summary:`${L.objective}: ${moduleTitle} — ${angle}.`,content};
 })}));
}'''
s=s[:start]+new_builder+'\n'
cat.write_text(s)

